head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.vScrenID = "ULDBNS23400.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 설명 : 권리행사(주식관련채권) 신고내역 조회
 ***********************************************/
scwin.fn_Search = function() {
    // 데이터셋 초기화
    dts_List2.removeAll();
    dts_List3.removeAll();
    var param = '';
    param += "&{P}V_ISUR_CD=" + $c.stf.getObjectValue(txb_IsurCd); //발행기관코드
    param += "&{P}V_ISUR_NM=" + $c.stf.getObjectValue(txb_IsurNm); //발행기관명
    param += "&{P}V_STD_CD=" + $c.stf.getObjectValue(txb_StdCd); //표준코드
    param += "&{P}V_ISU_NM=" + $c.stf.getObjectValue(txb_IsuNm); //종목명
    param += "&{P}V_PROCS_TP=" + $c.stf.getObjectValue(cmb_ProcsTp); //처리구분

    var dsNm = 'BNS_FRN_DECL_DTL_LIST';
    var qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnDeclDtlList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List1, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List1);
};


/********************************************** 
 * 설명 : 권리행사내역(주식관련사채) 조회
 ***********************************************/
scwin.fn_Search1 = function() {
    if (dts_List1.getRowPosition() < 1) return;
    var std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
    var dsNm = 'BNS_FRNIDS_SCD_LIST';
    var qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsScdList';
    var param = '';
    param += '&{P}V_STD_CD=' + std_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List2, dsNm, qryId, param);
};


/********************************************** 
 * 설명 : 채권신고담당자 조회
 ***********************************************/
scwin.fn_Search2 = function() {
    if (dts_List1.getRowPosition() < 1) return;
    var isur_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "ISUR_CD");
    var dsNm = 'BNS_BND_DECL_CHRG_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    var param = '&{P}V_ISUR_CD=' + isur_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List3, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_GetParListBndIsu
 * 설명       : 상장종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: "1" // 1 : 상장종목만, 2 : 상장폐지도 포함, else : 모두
            ,
        ISUR_NM: "",
        ISU_NM: $c.stf.getObjectValue(txb_IsuNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParListBndIsu
 * 설명       : 상장종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParListBndIsu = function(arrPar) {
    $c.stf.setObjectValue(txb_StdCd, arrPar[0].STD_CD);
    $c.stf.setObjectValue(txb_IsuNm, arrPar[0].ISU_NM);
};


/********************************************** 
 * 함수명   : fn_ShowIsurPopup
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsurPopup = function(obj) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(obj);
};

/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_IsurCd),
        ISUR_NM: $c.stf.getObjectValue(txb_IsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsurCd, arrPar[0].ISUR_CD);
    $c.stf.setObjectValue(txb_IsurNm, arrPar[0].ISUR_NM);
};


/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_FRN금리신고관리.xls";
    $c.data.downloadGridViewOffice(grd_List1, "Sheet1", "", 8, 0);
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(panel_Top);
    $c.bns.BnsPanelToGroupBox(panel_1);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_List1_OnRowPosChanged = function(row) {
    if (row > 0) {
        scwin.fn_Search1();
        scwin.fn_Search2();
    }
};
scwin.dts_List1_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List1);
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    //CloseWin(rowcount, grd_List2); 

};
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    //CloseWin(rowcount, grd_List3); 

};
scwin.btn_ISU_CD_SEARCH_onclick = function() {
    scwin.fn_GetPar = fn_GetParListBndIsu;
    scwin.fn_SetPar = fn_SetParListBndIsu;
    $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
};
scwin.txb_StdCd_onkeypress = function() {
    if (window.event.keyCode == 13 && $c.stf.getObjectValue(txb_StdCd) != "") {
        scwin.fn_Search();
    }
};
scwin.txb_StdCd_onchange = function() {
    $c.stf.setObjectValue(txb_IsuNm, "");
};
scwin.txb_IsuNm_onchange = function() {
    $c.stf.setObjectValue(txb_StdCd, "");
};
scwin.txb_IsuNm_onkeypress = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_GetPar = fn_GetParListBndIsu;
        scwin.fn_SetPar = fn_SetParListBndIsu;
        $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
    }
};
scwin.dts_List1_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List2_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List3_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.image_1_onclick = function() {
    // 접수/처리 버튼 클릭...
    if (dts_List1.getTotalRow() < 1) {
        return;
    }
    var std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
    var procs_tp = dts_List1.getCellData(dts_List1.getRowPosition(), "PROCS_TP"); // 처리현황

    var url = "/bnsisuchg/ULDBNS15100.gfm?STD_CD=" + std_cd + "&PROCS_TP=" + procs_tp;
    $c.frame.path("../").GWinOpen("BNS15100", url, "FRN변동금리 변경_BNS15100", 0, 0, 1300, 800, "");
};
scwin.txb_IsurCd_onkeypress = function() {
    if (window.event.keyCode == 13 && $c.stf.getObjectValue(txb_IsurCd) != "") {
        scwin.fn_Search();
    }
};
scwin.txb_IsurCd_onchange = function() {
    $c.stf.setObjectValue(txb_IsurNm, "");
};
scwin.img_CoSearch_onclick = function() {
    scwin.fn_ShowIsurPopup(img_CoSearch); //발행기관팝업 오픈

};
scwin.txb_IsurNm_onchange = function() {
    $c.stf.setObjectValue(txb_IsurCd, "");
};
scwin.txb_IsurNm_onkeypress = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_ShowIsurPopup(img_CoSearch); //발행기관팝업 오픈

    }
};
scwin.btn_Excel_onclick = function() {
    if (dts_List1.getTotalRow() > 0) {
        scwin.fn_ExcelDown();
    }
};
